DROP TABLE IF EXISTS `infrastructure_assets`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `infrastructure_assets` (
  `asset_id` bigint NOT NULL AUTO_INCREMENT,
  `dataset_id` bigint NOT NULL,
  `osm_id` varchar(100) DEFAULT NULL,
  `category` varchar(80) NOT NULL,
  `asset_name` varchar(200) DEFAULT NULL,
  `subtype` varchar(100) DEFAULT NULL,
  `latitude` double NOT NULL,
  `longitude` double NOT NULL,
  `geom` point NOT NULL /*!80003 SRID 4326 */,
  PRIMARY KEY (`asset_id`),
  UNIQUE KEY `dataset_id` (`dataset_id`,`osm_id`),
  SPATIAL KEY `idx_infrastructure_geom` (`geom`),
  CONSTRAINT `infrastructure_assets_ibfk_1` FOREIGN KEY (`dataset_id`) REFERENCES `dataset_versions` (`dataset_id`),
  CONSTRAINT `infrastructure_assets_chk_1` CHECK ((`latitude` between -(90) and 90)),
  CONSTRAINT `infrastructure_assets_chk_2` CHECK ((`longitude` between -(180) and 180))
) ENGINE=InnoDB AUTO_INCREMENT=4167 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
