/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `resource_priorities` (
  `priority_id` bigint NOT NULL AUTO_INCREMENT,
  `assessment_id` bigint NOT NULL,
  `priority_rank` int NOT NULL,
  `resource_type` varchar(100) DEFAULT NULL,
  `justification` text,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`priority_id`),
  UNIQUE KEY `assessment_id` (`assessment_id`,`priority_rank`),
  CONSTRAINT `resource_priorities_ibfk_1` FOREIGN KEY (`assessment_id`) REFERENCES `risk_assessments` (`assessment_id`),
  CONSTRAINT `resource_priorities_chk_1` CHECK ((`priority_rank` > 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
