CREATE TABLE `risk_assessments` (
  `assessment_id` bigint NOT NULL AUTO_INCREMENT,
  `location_id` bigint NOT NULL,
  `model_run_id` bigint NOT NULL,
  `flood_score` double DEFAULT NULL,
  `heat_score` double DEFAULT NULL,
  `infrastructure_score` double DEFAULT NULL,
  `overall_score` double DEFAULT NULL,
  `risk_level` varchar(30) DEFAULT NULL,
  `assessed_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`assessment_id`),
  UNIQUE KEY `location_id` (`location_id`,`model_run_id`),
  KEY `model_run_id` (`model_run_id`),
  CONSTRAINT `risk_assessments_ibfk_1` FOREIGN KEY (`location_id`) REFERENCES `spatial_locations` (`location_id`),
  CONSTRAINT `risk_assessments_ibfk_2` FOREIGN KEY (`model_run_id`) REFERENCES `model_runs` (`model_run_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
