  `osm_id` varchar(100) DEFAULT NULL,
  `road_name` varchar(200) DEFAULT NULL,
  `road_type` varchar(100) DEFAULT NULL,
  `maxspeed` varchar(50) DEFAULT NULL,
  `oneway` varchar(30) DEFAULT NULL,
  `length_km` double DEFAULT NULL,
  `latitude` double NOT NULL,
  `longitude` double NOT NULL,
  `representative_point` point NOT NULL /*!80003 SRID 4326 */,
  PRIMARY KEY (`road_id`),
  UNIQUE KEY `dataset_id` (`dataset_id`,`osm_id`),
  SPATIAL KEY `idx_roads_geom` (`representative_point`),
  CONSTRAINT `road_segments_ibfk_1` FOREIGN KEY (`dataset_id`) REFERENCES `dataset_versions` (`dataset_id`),
  CONSTRAINT `road_segments_chk_1` CHECK ((`latitude` between -(90) and 90)),
  CONSTRAINT `road_segments_chk_2` CHECK ((`longitude` between -(180) and 180))
) ENGINE=InnoDB AUTO_INCREMENT=186875 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
