DROP TABLE IF EXISTS `spatial_locations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `spatial_locations` (
  `location_id` bigint NOT NULL AUTO_INCREMENT,
  `location_type` varchar(30) NOT NULL,
  `external_key` varchar(150) DEFAULT NULL,
  `latitude` double NOT NULL,
  `longitude` double NOT NULL,
  `geom` point NOT NULL /*!80003 SRID 4326 */,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`location_id`),
  UNIQUE KEY `location_type` (`location_type`,`external_key`),
  SPATIAL KEY `idx_spatial_locations_geom` (`geom`),
  CONSTRAINT `spatial_locations_chk_1` CHECK ((`location_type` in (_cp850'grid_point',_cp850'plot'))),
  CONSTRAINT `spatial_locations_chk_2` CHECK ((`latitude` between -(90) and 90)),
  CONSTRAINT `spatial_locations_chk_3` CHECK ((`longitude` between -(180) and 180))
) ENGINE=InnoDB AUTO_INCREMENT=14707 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

